try { new Function('X', 'applyMacros', "/* 🏠 我们的小屋：一间只属于你们俩的小房间。一起做过的事会变成屋里的小物件——合照变成墙上的相框、散步捡回一片叶子、做到的约定变成一张奖状、捡到的漂流瓶摆在窗台……TA 也会时不时添一件东西，每件都有一段故事。东西能拖来拖去摆 */\nif (window.__gyxHome) return; window.__gyxHome = 1;\nX.feat('gyxHome', { n: '🏠 我们的小屋', desc: '一起做过的事变成屋里的小物件，每件都有故事，能自己摆' });\nconst S = X.store('home');\nlet D = { rooms: {}, cfg: { wall: 0 } };   // rooms[cid] = {items:[{id, ico, name, story, x, y, at, src, by}]}\nconst WALLS = [['#f6efe6', '#d9c3a5', '暖木'], ['#eef3f8', '#b9c7d6', '清晨'], ['#fbeef2', '#e3b7c4', '粉色'], ['#2c2f45', '#5a4a3d', '夜晚']];\nconst roomOf = cid => (D.rooms[String(cid)] = D.rooms[String(cid)] || { items: [] });\nfunction put(cid, o) { const R = roomOf(cid); if (o.src && (R.items.some(x => x.src === o.src) || (D.gone || []).includes(o.src))) return null; const it = Object.assign({ id: 'hm' + Date.now().toString(36) + Math.random().toString(36).slice(2, 4), x: X.rnd(.08, .86), y: o.ico && /🖼️|🏅|🗓️|🌌/.test(o.ico) ? X.rnd(.08, .4) : X.rnd(.55, .85), at: Date.now(), by: 'auto' }, o); R.items.push(it); return it; }\nfunction collect() {\n    let n = 0; X.chars().forEach(c => { const cid = String(c.id);\n        try { (window.gyxDuoData ? window.gyxDuoData().pics : []).filter(x => x.cid === cid).forEach(x => { if (put(cid, { ico: '🖼️', name: '合照相框', story: `${new Date(x.at).toLocaleDateString()} 拍的。TA 说：「${x.say}」`, src: 'duo:' + x.id, img: x.src })) n++; }); } catch (e) {}\n        try { (window.gyxWalkData ? window.gyxWalkData().walks : []).filter(x => x.cid === cid).forEach(x => { if (put(cid, { ico: X.pick(['🍂', '🌿', '🪨', '🌼']), name: '散步捡回来的', story: `${new Date(x.start).toLocaleDateString()} 一起走了 ${Math.round(x.dist)} 米。${x.diary || ''}`, src: 'walk:' + x.id })) n++; }); } catch (e) {}\n        try { (window.gyxPromiseData ? window.gyxPromiseData().list : []).filter(x => x.cid === cid && x.done === true).forEach(x => { if (put(cid, { ico: '🏅', name: '奖状', story: `约好的「${x.what}」，做到了。${x.reward ? '奖励：' + x.reward : ''}`, src: 'pr:' + x.id })) n++; }); } catch (e) {}\n        try { (window.gyxBottleData ? window.gyxBottleData().got : []).filter(x => x.kept && x.from === cid).forEach(x => { if (put(cid, { ico: '🍾', name: '窗台上的漂流瓶', story: x.text, src: 'bt:' + x.id })) n++; }); } catch (e) {}\n    }); return n;\n}\nasync function gift(c) {\n    const R = roomOf(c.id), have = R.items.map(x => x.name).join('、');\n    let j = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n你们有一间小屋，现在屋里有：${have || '（空的）'}。\\n你想给小屋添一件小东西，和你们最近的事有关。\\n最近的聊天：\\n${X.recent(c, 16)}\\n只输出 JSON：{\"ico\":\"一个 emoji\",\"name\":\"东西的名字（8 字内）\",\"story\":\"为什么放这个（你的口吻，40~80 字）\"}`));\n    if (!j || !j.name) { const P = [['🪴', '一盆小绿萝', '它很好养，跟我一样，你给一点点关心就能长很久。'], ['🕯️', '一根香薰蜡烛', '下雨天点上，屋里就有你喜欢的味道了。'], ['🧸', '小熊', '我不在的时候让它陪你。不许抱它比抱我还紧。'], ['☕', '两个马克杯', '一个你的一个我的，杯底写了名字。'], ['📻', '旧收音机', '晚上开着，像有人在说话，你就不会怕了。'], ['🧣', '一条围巾', '挂在门口，出门记得戴。'], ['🎐', '风铃', '风一吹它就响，像我在叫你。']]; const p = X.pick(P.filter(x => !R.items.some(i => i.name === x[1])).concat([P[0]])); j = { ico: p[0], name: p[1], story: (X.cards(['情话'], c, 1)[0] || p[2]) }; }\n    const it = put(c.id, { ico: String(j.ico || '🎁').slice(0, 4), name: String(j.name).slice(0, 12), story: X.plain(j.story), by: 'ta' }); await S.set('d', D); return it;\n}\nlet DRAG = null;\nwindow.gyxHomeDown = (e, cid, id) => { e.preventDefault(); e.stopPropagation(); DRAG = { cid, id, moved: false }; const mv = ev => { const room = document.getElementById('gyxHomeRm'), r = room.getBoundingClientRect(), p = ev.touches ? ev.touches[0] : ev, it = roomOf(cid).items.find(x => x.id === id); if (!it) return; DRAG.moved = true; it.x = Math.max(0, Math.min(.94, (p.clientX - r.left) / r.width - .03)); it.y = Math.max(0, Math.min(.9, (p.clientY - r.top) / r.height - .05)); const el = document.getElementById('hmi_' + id); if (el) { el.style.left = it.x * 100 + '%'; el.style.top = it.y * 100 + '%'; } }, up = () => { removeEventListener('mousemove', mv); removeEventListener('touchmove', mv); removeEventListener('mouseup', up); removeEventListener('touchend', up); if (DRAG && !DRAG.moved) window.gyxHomeSee(cid, id); DRAG = null; S.set('d', D); }; addEventListener('mousemove', mv); addEventListener('touchmove', mv, { passive: false }); addEventListener('mouseup', up); addEventListener('touchend', up); };\nwindow.gyxHomeSee = (cid, id) => { const it = roomOf(cid).items.find(x => x.id === id), b = document.getElementById('gyxHomeInfo'); if (!it || !b) return; b.innerHTML = `<div style=\"display:flex;gap:10px;align-items:center\"><span style=\"font-size:34px\">${it.img ? `<img src=\"${it.img}\" style=\"width:46px;height:46px;object-fit:cover;border-radius:6px\">` : X.esc(it.ico)}</span><div style=\"flex:1\"><b contenteditable=\"true\" onblur=\"gyxHomeEdit('${cid}','${id}','name',this.innerText.trim())\">${X.esc(it.name)}</b><div class=\"gyx-tip\">${new Date(it.at).toLocaleDateString()} · ${it.by === 'ta' ? 'TA 放的' : it.by === 'me' ? '你放的' : '一起做过的事'}</div></div><span class=\"gyx-chip\" onclick=\"gyxHomeEdit('${cid}','${id}','__del')\">收起来</span></div><div contenteditable=\"true\" style=\"margin-top:6px;outline:none;line-height:1.7\" onblur=\"gyxHomeEdit('${cid}','${id}','story',this.innerText.trim())\">${X.esc(it.story || '')}</div>`; };\nwindow.gyxHomeEdit = async (cid, id, k, v) => { const R = roomOf(cid), it = R.items.find(x => x.id === id); if (!it) return; if (k === '__del') { R.items.splice(R.items.indexOf(it), 1); if (it.src) (D.gone = D.gone || []).push(it.src); await S.set('d', D); window.gyxHomeOpen(cid); return; } it[k] = v; await S.set('d', D); };\nwindow.gyxHomeAdd = async cid => { const ico = (document.getElementById('gyxHmIco') || {}).value || '🎁', nm = ((document.getElementById('gyxHmNm') || {}).value || '').trim(); if (!nm) return; const it = put(cid, { ico: ico.trim().slice(0, 4), name: nm, story: ((document.getElementById('gyxHmSt') || {}).value || '').trim(), by: 'me' }); await S.set('d', D); window.gyxHomeOpen(cid); if (it) setTimeout(() => window.gyxHomeSee(cid, it.id), 50); };\nwindow.gyxHomeGift = async cid => { const c = X.char(cid); if (!c) return; const it = await gift(c); window.gyxHomeOpen(cid); if (it) setTimeout(() => window.gyxHomeSee(cid, it.id), 50); };\nwindow.gyxHomeWall = v => { D.cfg.wall = v; S.set('d', D); window.gyxHomeOpen(); };\nwindow.gyxHomeOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id); if (collect()) S.set('d', D); const R = roomOf(cid), w = WALLS[D.cfg.wall] || WALLS[0];\n    X.panel('gyxHomeOv', '🏠 我们的小屋', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxHomeOpen')}${WALLS.map((x, i) => `<span class=\"gyx-chip${i === D.cfg.wall ? ' on' : ''}\" onclick=\"gyxHomeWall(${i})\">${x[2]}</span>`).join('')}</div>\n        <div id=\"gyxHomeRm\" class=\"hm-rm\" style=\"--wa:${w[0]};--fl:${w[1]}\"><div class=\"hm-win\">🪟</div>${R.items.map(x => `<div id=\"hmi_${x.id}\" class=\"hm-it\" style=\"left:${x.x * 100}%;top:${x.y * 100}%\" onmousedown=\"gyxHomeDown(event,'${cid}','${x.id}')\" ontouchstart=\"gyxHomeDown(event,'${cid}','${x.id}')\" title=\"${X.esc(x.name)}\">${x.img ? `<img src=\"${x.img}\">` : X.esc(x.ico)}</div>`).join('')}${R.items.length ? '' : `<div class=\"hm-empty\">${X.v('屋里还空空的。', '一起做点什么，这里就会慢慢满起来。')}</div>`}</div>\n        <div id=\"gyxHomeInfo\" class=\"gyx-card\">${R.items.length ? X.v('点一件东西看它的故事，拖着能挪位置。', '每件东西都有一段故事。') : '拍合照、散步、做到约定、捡漂流瓶……都会在这里留下东西。'}</div>\n        <div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"this.disabled=true;gyxHomeGift('${cid}')\">让 TA 添一件</button></div>\n        <div class=\"gyx-row\"><input id=\"gyxHmIco\" class=\"gyx-who\" style=\"width:54px\" value=\"🎁\"><input id=\"gyxHmNm\" class=\"gyx-who\" style=\"flex:1\" placeholder=\"东西\"><input id=\"gyxHmSt\" class=\"gyx-who\" style=\"flex:2\" placeholder=\"它的故事\"><button class=\"gyx-btn\" onclick=\"gyxHomeAdd('${cid}')\">放进去</button></div>`);\n};\nasync function tick() { if (!X.on('gyxHome')) return; if (collect()) await S.set('d', D); }\nX.ctx(id => { const R = D.rooms[String(id)]; if (!R || !R.items.length) return ''; return `【你们的小屋里有】${R.items.slice(-8).map(x => x.name).join('、')}。`; }, 'gyxHome');\nX.action({ key: 'gyx_home', label: '给你们的小屋添一件东西', hint: '我们的小屋', need: c => !roomOf(c.id).items.some(x => x.by === 'ta' && Date.now() - x.at < 5 * 864e5),\n    run: async c => { const it = await gift(c); if (!it) return null; return (await X.reach(c, `你刚给你们的小屋添了「${it.name}」。告诉她，说说为什么放它`)) ? '给小屋添了' + it.name : null; } }, 'gyxHome');\nX.today(() => { const rows = []; X.chars().forEach(c => roomOf(c.id).items.filter(x => X.day(new Date(x.at)) === X.day()).forEach(x => rows.push({ t: x.ico, x: X.esc(x.name) + (x.by === 'ta' ? '（TA 放的）' : ''), go: `gyxHomeOpen('${c.id}')` }))); return { title: '🏠 小屋里多了', rows }; }, 'gyxHome');\nX.widget('gyxHomeW', { n: '我们的小屋', sizes: ['s', 'm'], tap: () => window.gyxHomeOpen(), r: w => { const c = X.cur(), L = c ? roomOf(c.id).items : []; return X.gw(w, '🏠', '我们的小屋', L.length ? [L.slice(-6).map(x => x.img ? '🖼️' : X.esc(x.ico)).join(''), L.length + ' 件东西'] : ['还空着']); } }, 'gyxHome');\nX.mem({ k: 'gyxHome', ico: '🏠', n: '我们的小屋', d: '屋里每件东西和它的故事', items: c => roomOf(c.id).items, text: x => x.name + '：' + (x.story || ''), edit: (x, v) => { const i = v.indexOf('：'); if (i > 0) { x.name = v.slice(0, i); x.story = v.slice(i + 1); } else x.story = v; }, del: (c, i) => { const it = roomOf(c.id).items.splice(i, 1)[0]; if (it && it.src) (D.gone = D.gone || []).push(it.src); }, meta: x => x.ico + ' · ' + new Date(x.at).toLocaleDateString(), save: () => S.set('d', D) }, 'gyxHome');\nX.css('gyxHomeCss', `.hm-rm{position:relative;height:52vh;border-radius:18px;overflow:hidden;background:linear-gradient(var(--wa) 0 62%,var(--fl) 62%);box-shadow:inset 0 -2px 0 rgba(0,0,0,.05);touch-action:none}.hm-win{position:absolute;left:40%;top:10%;font-size:56px;opacity:.7}.hm-it{position:absolute;font-size:34px;cursor:grab;user-select:none;filter:drop-shadow(0 3px 3px rgba(0,0,0,.18));transition:transform .15s}.hm-it:hover{transform:scale(1.15)}.hm-it img{width:44px;height:44px;object-fit:cover;border:4px solid #fff;border-radius:3px;box-shadow:0 2px 6px rgba(0,0,0,.25)}.hm-empty{position:absolute;left:0;right:0;top:44%;text-align:center;color:#a99;font-size:14px}`);\nX.mini({ id: 'gyxHome', icon: '🏠', title: '我们的小屋', desc: '一起做过的事变成屋里的小物件', cat: '回忆', onOpen: () => window.gyxHomeOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.rooms = D.rooms || {}; D.cfg = Object.assign({ wall: 0 }, D.cfg || {}); setTimeout(tick, 30000); setInterval(tick, 120000); })();\n\n//# sourceURL=gyx-plugin/我们的小屋.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🏠 我们的小屋 出错：', e); }
/* ==== 🍁 随机掉落收藏册 ==== */
try { new Function('X', 'applyMacros', "/* 🍁 随机掉落收藏册：打开 App 的时候，屏幕上偶尔会飘下来一个 TA 留的小东西——一片叶子、一颗糖、一张小纸条、一枚星星……点一下捡起来，收进图鉴，第一次捡到的 TA 会附一句话。有普通、稀有、传说三种，传说的很难遇到 */\nif (window.__gyxDrop) return; window.__gyxDrop = 1;\nX.feat('gyxDrop', { n: '🍁 随机掉落收藏册', desc: '屏幕上偶尔飘下 TA 留的小东西，捡起来收进图鉴' });\nconst S = X.store('drop');\nconst ITEMS = [\n    ['leaf', '🍁', '一片枫叶', 1], ['leaf2', '🍃', '一片绿叶', 1], ['petal', '🌸', '一片花瓣', 1], ['candy', '🍬', '一颗糖', 1], ['choco', '🍫', '一块巧克力', 1], ['note', '📝', '一张小纸条', 1], ['shell', '🐚', '一枚贝壳', 1], ['button', '🔘', '一颗纽扣', 1], ['ticket', '🎫', '一张旧票根', 1], ['feather', '🪶', '一根羽毛', 1], ['stone', '🪨', '一颗小石子', 1], ['clover3', '☘️', '三叶草', 1], ['cookie', '🍪', '一块小饼干', 1], ['bandaid', '🩹', '一张创可贴', 1], ['pencil', '✏️', '一截铅笔', 1], ['sock', '🧦', '一只袜子', 1],\n    ['star', '⭐', '一颗星星', 2], ['moon', '🌙', '一弯月亮', 2], ['heart', '💗', '一颗心', 2], ['letter', '💌', '一封没寄出的信', 2], ['ring', '💍', '一枚戒指（玩具的）', 2], ['key', '🔑', '一把小钥匙', 2], ['bear', '🧸', '一只小熊', 2], ['clover4', '🍀', '四叶草', 2], ['photo', '🖼️', '一张拍立得', 2], ['shellpearl', '🦪', '藏着珍珠的贝壳', 2], ['music', '🎵', '一段旋律', 2], ['balloon', '🎈', '一只气球', 2], ['umbrella', '☂️', '一把小伞', 2],\n    ['comet', '☄️', '一颗流星', 3], ['crown', '👑', '一顶小王冠', 3], ['rainbow', '🌈', '一截彩虹', 3], ['crystal', '🔮', '会发光的水晶球', 3], ['unicorn', '🦄', '一只独角兽', 3], ['firefly', '✨', '一瓶萤火虫', 3], ['lovekey', '🗝️', '打开 TA 心的钥匙', 3]\n];\nconst RAR = { 1: ['普通', '#9aa5b1'], 2: ['稀有', '#4c8dff'], 3: ['传说', '#ff9f1a'] };\nconst NOTE = { 1: ['路上看到的，觉得你会喜欢。', '顺手给你留的。', '收好，别弄丢了。', '今天想你的时候捡的。'], 2: ['这个可不好找，找了很久。', '留给你的，只有你能捡到。', '偷偷放这儿的，被你发现了。'], 3: ['……这个是我最珍贵的东西，给你了。', '能捡到这个，说明我们缘分很深。', '这个世界上只有一个，现在是你的了。'] };\nlet D = { got: {}, day: '', today: 0, cfg: { p: 35, max: 5 } };   // got[cid][itemId] = {n, first, note}\nfunction roll() { const r = Math.random(); const rar = r < .04 ? 3 : r < .25 ? 2 : 1; return X.pick(ITEMS.filter(i => i[3] === rar)); }\nfunction drop(it, c) {\n    if (document.getElementById('gyxDropIt') || !it) return false; c = c || X.cur(); if (!c) return false;\n    const el = document.createElement('div'); el.id = 'gyxDropIt'; el.className = 'drop-it r' + it[3]; el.innerHTML = `<span>${it[1]}</span>`; el.title = '点一下捡起来';\n    el.style.left = Math.round(X.rnd(.12, .82) * innerWidth) + 'px'; el.setAttribute('data-i', it[0]); el.setAttribute('data-c', String(c.id));\n    el.onclick = () => window.gyxDropPick(); document.body.appendChild(el);\n    setTimeout(() => { const e = document.getElementById('gyxDropIt'); if (e && e === el) { e.classList.add('gone'); setTimeout(() => e.remove(), 900); } }, 60000);\n    return true;\n}\nwindow.gyxDropNow = (itemId, cid) => { const it = itemId ? ITEMS.find(i => i[0] === itemId) : roll(); return drop(it, X.char(cid) || X.cur()); };\nwindow.gyxDropPick = async () => {\n    const el = document.getElementById('gyxDropIt'); if (!el) return null; const id = el.getAttribute('data-i'), cid = el.getAttribute('data-c'), it = ITEMS.find(i => i[0] === id), c = X.char(cid);\n    el.classList.add('got'); setTimeout(() => el.remove(), 700); if (!it || !c) return null;\n    const G = (D.got[cid] = D.got[cid] || {}), first = !G[id];\n    if (first) { let note = X.bailu() ? null : X.plain(await X.ask(`${X.who(c)}\\n你偷偷给她留了「${it[2]}」，她刚捡到了。写一句附在上面的小纸条（20 字以内）。`) || ''); G[id] = { n: 1, first: Date.now(), note: note || X.pick(X.cards(['情话'], c, 1).filter(x => x.length <= 24).concat(NOTE[it[3]])) }; }\n    else G[id].n++;\n    await S.set('d', D);\n    X.toast(`${it[1]} ${first ? X.v('新收集', '第一次捡到', '图鉴 +1') : '又捡到一个'}：${it[2]}`, first ? `${RAR[it[3]][0]} · ${X.name(c)}：${G[id].note}` : `已经有 ${G[id].n} 个了`);\n    return { id, first, n: G[id].n };\n};\nasync function maybe(force) {\n    if (!X.on('gyxDrop')) return; const d = X.day(); if (D.day !== d) { D.day = d; D.today = 0; }\n    if (D.today >= (+D.cfg.max || 5) || document.hidden) return; if (!force && Math.random() * 100 >= (+D.cfg.p || 35)) return;\n    if (drop(roll())) { D.today++; await S.set('d', D); }\n}\nwindow.gyxDropCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nwindow.gyxDropData = () => D;\nwindow.gyxDropOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), G = D.got[cid] || {}, n = Object.keys(G).length;\n    X.panel('gyxDropOv', '🍁 收藏册', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxDropOpen')}<span class=\"gyx-tip\">${n} / ${ITEMS.length} · 今天掉了 ${D.day === X.day() ? D.today : 0} 个</span></div>\n        ${[1, 2, 3].map(r => `<div class=\"drop-h\" style=\"color:${RAR[r][1]}\">${RAR[r][0]}</div><div class=\"drop-grid\">${ITEMS.filter(i => i[3] === r).map(i => { const g = G[i[0]]; return `<div class=\"${g ? 'on' : ''}\" title=\"${g ? X.esc(g.note) : ''}\"><span>${g ? i[1] : '？'}</span><b>${g ? X.esc(i[2]) : '？？？'}</b>${g ? `<em>×${g.n}</em><i>${X.esc(g.note)}</i>` : ''}</div>`; }).join('')}</div>`).join('')}\n        <div class=\"gyx-row gyx-tip\">打开 App 时掉落的概率 <input class=\"gyx-who\" type=\"number\" min=\"0\" max=\"100\" value=\"${D.cfg.p}\" style=\"width:56px\" onchange=\"gyxDropCfg('p',+this.value)\">% · 一天最多 <input class=\"gyx-who\" type=\"number\" min=\"0\" value=\"${D.cfg.max}\" style=\"width:50px\" onchange=\"gyxDropCfg('max',+this.value)\"> 个</div>`);\n};\nX.ctx(id => { const G = D.got[String(id)] || {}, k = Object.keys(G); if (!k.length) return ''; const last = k.sort((a, b) => G[b].first - G[a].first)[0], it = ITEMS.find(i => i[0] === last); return `【你偷偷给她留的小东西】她已经捡到 ${k.length} 种，最近一个是「${it ? it[2] : last}」。`; }, 'gyxDrop');\nX.action({ key: 'gyx_drop', label: '偷偷在她的屏幕上留个小东西', hint: '随机掉落', need: () => !document.getElementById('gyxDropIt') && !document.hidden, run: async c => drop(roll(), c) ? '留了个小东西' : null }, 'gyxDrop');\nX.today(() => { const rows = []; X.chars().forEach(c => { const G = D.got[String(c.id)] || {}; Object.keys(G).filter(k => X.day(new Date(G[k].first)) === X.day()).forEach(k => { const it = ITEMS.find(i => i[0] === k); if (it) rows.push({ t: it[1], x: '新收集：' + it[2], go: `gyxDropOpen('${c.id}')` }); }); }); return { title: '🍁 收藏册', rows }; }, 'gyxDrop');\nX.widget('gyxDropW', { n: '收藏册', sizes: ['s', 'm'], tap: () => window.gyxDropOpen(), r: w => { const c = X.cur(), G = c ? D.got[String(c.id)] || {} : {}, k = Object.keys(G); return X.gw(w, k.length ? (ITEMS.find(i => i[0] === k.sort((a, b) => G[b].first - G[a].first)[0]) || [, '🍁'])[1] : '🍁', '收藏册', [k.length + ' / ' + ITEMS.length, k.some(x => (ITEMS.find(i => i[0] === x) || [])[3] === 3) ? '有传说级！' : '']); } }, 'gyxDrop');\nX.mem({ k: 'gyxDrop', ico: '🍁', n: '收藏册', d: '捡到的小东西和 TA 附的话', items: c => { const G = D.got[String(c.id)] || {}; return Object.keys(G).map(k => Object.assign(G[k], { k })); }, text: x => x.note, edit: (x, v) => { x.note = v; }, del: (c, i) => { const G = D.got[String(c.id)] || {}; delete G[Object.keys(G)[i]]; }, meta: x => { const it = ITEMS.find(i => i[0] === x.k); return (it ? it[1] + ' ' + it[2] : x.k) + ' ×' + x.n; }, save: () => S.set('d', D) }, 'gyxDrop');\nX.css('gyxDropCss', `.drop-it{position:fixed;top:-60px;z-index:99990;font-size:40px;cursor:pointer;animation:dropf 6s ease-in forwards,drops 2.4s ease-in-out infinite;filter:drop-shadow(0 4px 6px rgba(0,0,0,.2));user-select:none}.drop-it span{display:inline-block}.drop-it.r2 span{filter:drop-shadow(0 0 8px #7fb0ff)}.drop-it.r3 span{filter:drop-shadow(0 0 12px #ffc95c);animation:dropg 1.2s ease-in-out infinite}@keyframes dropf{to{top:62vh}}@keyframes drops{50%{transform:translateX(18px) rotate(14deg)}}@keyframes dropg{50%{transform:scale(1.15)}}.drop-it.got{animation:dropgot .6s forwards}@keyframes dropgot{to{transform:scale(2) translateY(-30px);opacity:0}}.drop-it.gone{transition:opacity .8s;opacity:0}.drop-h{font-weight:800;margin:12px 0 6px;font-size:13px}.drop-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px}.drop-grid>div{border-radius:14px;background:#f5f5f7;padding:8px 6px;text-align:center;position:relative;opacity:.55}.drop-grid>div.on{opacity:1;background:#fffaf2}.drop-grid span{font-size:28px;display:block}.drop-grid b{display:block;font-size:12px}.drop-grid em{position:absolute;top:4px;right:6px;font-style:normal;font-size:11px;color:#c07a2a}.drop-grid i{display:block;font-style:normal;font-size:10.5px;color:#999;line-height:1.35;margin-top:2px}`);\nX.mini({ id: 'gyxDrop', icon: '🍁', title: '随机掉落收藏册', desc: '捡 TA 留在屏幕上的小东西', cat: '回忆', onOpen: () => window.gyxDropOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.got = D.got || {}; D.cfg = Object.assign({ p: 35, max: 5 }, D.cfg || {}); setTimeout(() => maybe(), 20000); setInterval(() => { if (Math.random() < .2) maybe(true); }, 900000); })();\n\n//# sourceURL=gyx-plugin/随机掉落收藏册.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🍁 随机掉落收藏册 出错：', e); }
